import {Game,CHAPTERS,clamp} from './engine.mjs';
import {Renderer} from './render.mjs';
const $=id=>document.getElementById(id);
const storageKey='spider-pixel-stories-v1';
let save={unlocked:0,best:[0,0,0,0,0],completed:[],sound:false};
try{const data=JSON.parse(localStorage.getItem(storageKey)||'null');if(data&&typeof data==='object'){save.unlocked=clamp(Number(data.unlocked)||0,0,4);save.best=Array.from({length:5},(_,i)=>Math.max(0,Number(data.best?.[i])||0));save.completed=Array.isArray(data.completed)?data.completed.filter(n=>Number.isInteger(n)&&n>=0&&n<5):[];save.sound=data.sound===true;}}catch{}
const persist=()=>{try{localStorage.setItem(storageKey,JSON.stringify(save));}catch{}};
let audio=null;let sound=save.sound;
function audioUnlock(){if(sound){try{audio??=new(window.AudioContext||window.webkitAudioContext)();if(audio.state==='suspended')audio.resume();}catch{sound=false;updateSound();}}}
function tone(freq,start,duration,type='square',volume=.03,endFreq){if(!audio||!sound||audio.state!=='running')return;const osc=audio.createOscillator(),gain=audio.createGain(),at=audio.currentTime+start;osc.type=type;osc.frequency.setValueAtTime(freq,at);if(endFreq)osc.frequency.exponentialRampToValueAtTime(endFreq,at+duration);gain.gain.setValueAtTime(0,at);gain.gain.linearRampToValueAtTime(volume,at+.01);gain.gain.exponentialRampToValueAtTime(.0001,at+duration);osc.connect(gain);gain.connect(audio.destination);osc.start(at);osc.stop(at+duration+.02);}
function sfx(name){const notes={collect:[660,880],rescue:[523,659,784,1047],complete:[523,659,784,1047,1319],defeat:[220,440],jump:[200,400],web:[800],swing:[420],hit:[100,65]};if(!sound)return;for(const [i,f] of(notes[name]||[]).entries())tone(f,i*.065,name==='swing'?.2:.12,name==='hit'?'sawtooth':'square',name==='hit'?.025:.018,name==='web'?140:name==='swing'?120:undefined);}
let renderer;let toastTimer;let transitionTimer;let pendingChapter=0;let storyAction='start';let dialogPaused=false;let lastHud=0;
const game=new Game(handleEvent);renderer=new Renderer($('game'),game);
const overlays=['home-overlay','story-overlay','pause-overlay','gameover-overlay'];
function showOverlay(id){for(const overlay of overlays)$(overlay).hidden=overlay!==id;const playing=game.mode==='playing';$('hud').hidden=game.mode==='menu'||id==='story-overlay';$('touch-controls').hidden=!playing||!touch;}
function clearInputs(){heldKeys.clear();activePointers.clear();for(const key of Object.keys(game.inputs))game.inputs[key]=false;document.querySelectorAll('[data-control]').forEach(b=>b.classList.remove('pressed'));}
let touch=matchMedia('(pointer:coarse)').matches||navigator.maxTouchPoints>0||innerWidth<=720;
if(touch)document.body.classList.add('has-touch');
function updateSound(){const button=$('sound-button');button.setAttribute('aria-pressed',String(sound));button.setAttribute('aria-label',sound?'Mute game sound':'Enable game sound');button.innerHTML=sound?'<svg viewBox="0 0 24 24"><path d="M11 5L6 9H3v6h3l5 4zM15 8a6 6 0 010 8m3-11a10 10 0 010 14"/></svg>':'<svg viewBox="0 0 24 24"><path d="M11 5L6 9H3v6h3l5 4zM16 9l5 6m0-6l-5 6"/></svg>';}
$('sound-button').addEventListener('click',()=>{sound=!sound;save.sound=sound;persist();audioUnlock();updateSound();if(sound)sfx('collect');});updateSound();
function toast(text){$('toast').textContent=text;$('toast').classList.add('visible');clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('toast').classList.remove('visible'),3300);}
function updateHud(){if(!game.config)return;const progress=Math.min(game.progress(),game.config.target);$('hud-chapter').textContent=`CHAPTER ${String(game.chapter+1).padStart(2,'0')} / 05`;
  const objective={tokens:`Web tokens ${progress} / 8`,rescue:`Neighbors saved ${progress} / 3`,drones:`Drones webbed ${progress} / 6`,cells:`Power cells ${progress} / 5`,boss:`Goblin ${Math.max(0,game.boss?.hp??16)} / 16 HP`};$('hud-objective').textContent=game.ready()&&game.config.type!=='boss'?'Reach the rooftop beacon →':objective[game.config.type];$('objective-progress').style.width=(progress/game.config.target*100)+'%';$('hearts').innerHTML=Array.from({length:5},(_,i)=>`<span${i>=game.player.hp?' class="lost"':''}>♥</span>`).join(' ');$('hearts').setAttribute('aria-label',`${game.player.hp} of 5 health points`);$('score').textContent=String(game.score).padStart(6,'0');const shell=$('game-shell');shell.dataset.playerX=Math.round(game.player.x);shell.dataset.playerY=Math.round(game.player.y);shell.dataset.swinging=String(!!game.rope);
}
function updateChapters(){const grid=$('chapter-grid');grid.replaceChildren();CHAPTERS.forEach((ch,i)=>{const b=document.createElement('button');b.className='chapter-card'+(i===save.unlocked?' current':'');b.disabled=i>save.unlocked;b.setAttribute('aria-label',`Chapter ${i+1}: ${ch.short}${b.disabled?', locked':', play'}`);const number=document.createElement('span');number.className='chapter-number';number.textContent=String(i+1).padStart(2,'0');const thumb=document.createElement('canvas');thumb.className='chapter-thumb';thumb.setAttribute('aria-hidden','true');renderer.thumbnail(thumb,i);const info=document.createElement('span');info.className='chapter-info';const small=document.createElement('small');small.textContent=ch.district;const strong=document.createElement('strong');strong.textContent=ch.short;info.append(small,strong);b.append(number,thumb,info);if(b.disabled){const lock=document.createElement('span');lock.className='chapter-lock';lock.innerHTML='<svg width="9" height="10" viewBox="0 0 12 14" fill="none" stroke="currentColor"><rect x="2" y="6" width="8" height="7" rx="1"/><path d="M4 6V3a2 2 0 014 0v3"/></svg>';b.append(lock);}else if(save.completed.includes(i)){b.classList.add('completed');const check=document.createElement('span');check.className='chapter-lock';check.textContent='✓';b.append(check);}b.addEventListener('click',()=>{audioUnlock();showChapter(i);$('game-shell').scrollIntoView({behavior:'smooth',block:'center'});});grid.append(b);});const total=save.best.reduce((a,b)=>a+b,0);if(total)$('best-label').textContent=`PERSONAL BEST ${String(total).padStart(6,'0')} / YOUR STORY, SAVED`;}
function wipe(callback){clearInputs();$('chapter-swipe').classList.remove('active');void $('chapter-swipe').offsetWidth;$('chapter-swipe').classList.add('active');clearTimeout(transitionTimer);transitionTimer=setTimeout(callback,370);setTimeout(()=>$('chapter-swipe').classList.remove('active'),880);}
function showChapter(index){game.mode='briefing';pendingChapter=index;storyAction='start';wipe(()=>{const ch=CHAPTERS[index];$('story-eyebrow').textContent=`CHAPTER ${String(index+1).padStart(2,'0')} / 05 · ${ch.district}`;$('story-title').textContent=ch.title;$('story-description').textContent=ch.description;$('story-objective').textContent=ch.objective;$('story-note').textContent=ch.hint;$('story-art').style.backgroundImage=`url('art/${ch.art}.png')`;$('comic-caption').textContent=ch.caption;$('story-button').innerHTML='LET’S DO THIS <span>→</span>';$('location').textContent=ch.district+', NEW YORK';$('clock-label').textContent=ch.time;showOverlay('story-overlay');$('story-button').focus({preventScroll:true});});}
function begin(index){audioUnlock();wipe(()=>{game.start(index);$('game-shell').classList.add('is-playing');showOverlay(null);updateHud();$('game').focus({preventScroll:true});$('bottom-status').textContent='YOUR NEIGHBORHOOD IS COUNTING ON YOU.';toast(CHAPTERS[index].hint);});}
function home(){clearInputs();game.mode='menu';$('game-shell').classList.remove('is-playing');$('location').textContent='QUEENS, NEW YORK';$('clock-label').textContent='GOLDEN HOUR · 6:42 PM';$('bottom-status').textContent='A CITY WORTH SAVING.';$('continue-button').hidden=save.unlocked===0&&!save.completed.length;$('continue-button').innerHTML=save.completed.length===5?'Replay your story <span>→</span>':'Continue your story <span>→</span>';showOverlay('home-overlay');updateChapters();}
function pause(){if(game.mode!=='playing')return;game.mode='paused';clearInputs();showOverlay('pause-overlay');$('resume-button').focus({preventScroll:true});}
function resume(){if(game.mode!=='paused')return;game.mode='playing';showOverlay(null);$('game').focus({preventScroll:true});}
function complete(e){save.unlocked=Math.max(save.unlocked,Math.min(4,e.chapter+1));save.best[e.chapter]=Math.max(save.best[e.chapter],e.score);if(!save.completed.includes(e.chapter))save.completed.push(e.chapter);persist();sfx('complete');updateChapters();const final=e.chapter===4;storyAction=final?'home':'next';pendingChapter=Math.min(4,e.chapter+1);wipe(()=>{$('story-eyebrow').textContent=final?'FIVE CHAPTERS. ONE AMAZING NEIGHBOR.':`CHAPTER ${String(e.chapter+1).padStart(2,'0')} COMPLETE`;$('story-title').textContent=final?'Your city.\nYour story.':'Nice work,\nneighbor.';$('story-description').textContent=final?'The lights are on. The neighbors are safe. The Goblin is gone. New York can sleep easy tonight — thanks to its friendly neighborhood Spider-Man.':e.chapter===2?'A clear sky, a little quiet, and time for a quick breather. Enjoy it while it lasts. There’s always another story around the corner.':`Another little corner of New York is a little safer. But the city isn’t done with you yet. Next stop: ${CHAPTERS[pendingChapter].district.toLowerCase()}.`;$('story-objective').textContent=`${e.score.toLocaleString()} POINTS · ${Math.floor(e.elapsed/60)}:${String(Math.floor(e.elapsed%60)).padStart(2,'0')} · ${game.player.hp}/5 HEALTH`;$('story-art').style.backgroundImage=`url('art/${final?'friendly':e.chapter===2?'breather':'sunset'}.png')`;$('comic-caption').textContent=final?'THE END. UNTIL TOMORROW.':'A MOMENT BETWEEN THE MADNESS.';$('story-button').innerHTML=final?'BACK TO THE NEIGHBORHOOD <span>↗</span>':'NEXT CHAPTER <span>→</span>';$('story-note').textContent=final?'Your best scores are saved. Replay any chapter to beat them.':'Progress saved. Take a breath — your next chapter is ready.';showOverlay('story-overlay');$('story-button').focus({preventScroll:true});});}
function handleEvent(e){if(e.type==='hud'){if(renderer)updateHud();}else if(e.type==='toast')toast(e.message);else if(e.type==='sound')sfx(e.sound);else if(e.type==='complete')complete(e);else if(e.type==='gameover'){clearInputs();$('gameover-score').textContent=game.score.toLocaleString();$('gameover-title').textContent=e.reason==='time'?'Time for a retry.':'One more try?';$('gameover-description').textContent=e.reason==='time'?'The power grid needs you a little faster. You know the rooftops now.':'Take a breath. Your neighborhood still needs you.';showOverlay('gameover-overlay');$('retry-button').focus({preventScroll:true});}}
$('start-button').addEventListener('click',()=>{audioUnlock();showChapter(0);});$('continue-button').addEventListener('click',()=>{audioUnlock();showChapter(save.completed.length===5?0:save.unlocked);});$('story-button').addEventListener('click',()=>{if(storyAction==='home')wipe(home);else if(storyAction==='next')showChapter(pendingChapter);else begin(pendingChapter);});
$('pause-button').addEventListener('click',pause);$('resume-button').addEventListener('click',resume);$('restart-button').addEventListener('click',()=>begin(game.chapter));$('retry-button').addEventListener('click',()=>begin(game.chapter));$('home-button').addEventListener('click',()=>wipe(home));$('gameover-home-button').addEventListener('click',()=>wipe(home));
const keys={ArrowLeft:'left',KeyA:'left',ArrowRight:'right',KeyD:'right',ArrowUp:'jump',KeyW:'jump',Space:'jump',KeyX:'swing',KeyC:'shoot'};
const heldKeys=new Set();function syncKeyboard(){Object.keys(game.inputs).forEach(control=>{game.inputs[control]=[...heldKeys].some(k=>keys[k]===control)||[...activePointers.values()].includes(control);});}
document.addEventListener('keydown',e=>{if($('controls-dialog').open)return;if(e.code==='KeyP'||e.code==='Escape'){if(e.repeat)return;if(game.mode==='playing'){e.preventDefault();pause();}else if(game.mode==='paused'){e.preventDefault();resume();}return;}if(keys[e.code]&&game.mode==='playing'){e.preventDefault();heldKeys.add(e.code);syncKeyboard();}});
document.addEventListener('keyup',e=>{heldKeys.delete(e.code);syncKeyboard();});
const activePointers=new Map();document.querySelectorAll('[data-control]').forEach(button=>{button.addEventListener('pointerdown',e=>{e.preventDefault();if(game.mode!=='playing')return;audioUnlock();button.setPointerCapture(e.pointerId);activePointers.set(e.pointerId,button.dataset.control);button.classList.add('pressed');syncKeyboard();if(button.dataset.control==='jump')game.jumpBuffer=.15;if(button.dataset.control==='shoot')game.shoot();});const release=e=>{activePointers.delete(e.pointerId);button.classList.remove('pressed');syncKeyboard();};button.addEventListener('pointerup',release);button.addEventListener('pointercancel',release);button.addEventListener('lostpointercapture',release);button.addEventListener('click',e=>{if(e.detail!==0||game.mode!=='playing')return;const control=button.dataset.control;audioUnlock();game.inputs[control]=true;button.classList.add('pressed');if(control==='jump')game.jumpBuffer=.15;if(control==='shoot')game.shoot();setTimeout(()=>{syncKeyboard();button.classList.remove('pressed');},180);});});
window.addEventListener('blur',()=>{heldKeys.clear();activePointers.clear();clearInputs();if(!$('controls-dialog').open)pause();});document.addEventListener('visibilitychange',()=>{if(document.hidden){heldKeys.clear();activePointers.clear();clearInputs();pause();}});
$('controls-tab').addEventListener('click',()=>{dialogPaused=game.mode==='playing';if(dialogPaused)pause();$('controls-dialog').showModal();});document.querySelectorAll('.dialog-close,.dialog-close-action').forEach(b=>b.addEventListener('click',()=>$('controls-dialog').close()));$('controls-dialog').addEventListener('click',e=>{const r=$('controls-dialog').getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)$('controls-dialog').close();});$('controls-dialog').addEventListener('close',()=>{if(dialogPaused)resume();dialogPaused=false;});
$('chapters-tab').addEventListener('click',()=>{$('chapter-section').scrollIntoView({behavior:'smooth',block:'center'});});$('play-tab').addEventListener('click',()=>{$('game-shell').scrollIntoView({behavior:'smooth',block:'center'});if(game.mode==='playing')$('game').focus({preventScroll:true});});
$('fullscreen-button').addEventListener('click',async()=>{const shell=$('game-shell');try{if(document.fullscreenElement)await document.exitFullscreen();else if(shell.classList.contains('expanded'))shell.classList.remove('expanded');else if(shell.requestFullscreen)await shell.requestFullscreen();else shell.classList.add('expanded');}catch{shell.classList.toggle('expanded');}renderer.resize();});document.addEventListener('fullscreenchange',()=>{$('fullscreen-button').setAttribute('aria-label',document.fullscreenElement?'Exit fullscreen':'Enter fullscreen');renderer.resize();});
new ResizeObserver(()=>{renderer.resize();touch=matchMedia('(pointer:coarse)').matches||navigator.maxTouchPoints>0||innerWidth<=720;document.body.classList.toggle('has-touch',touch);$('touch-controls').hidden=game.mode!=='playing'||!touch;}).observe($('game-viewport'));renderer.resize();home();let previous=performance.now();let accumulator=0;
function frame(now){const dt=Math.min((now-previous)/1000,.1);previous=now;accumulator+=dt;let n=0;while(accumulator>=1/120&&n<12){game.update(1/120);accumulator-=1/120;n++;}renderer.draw();if(now-lastHud>150&&game.mode==='playing'){updateHud();lastHud=now;}requestAnimationFrame(frame);}requestAnimationFrame(frame);
